import React from 'react';
import './Problem.css';

const Problem = () => {
  return (
    <section className="problem">
      <div className="container">
        <h2>Stop Losing Sales to Competitors</h2>
        <p>
          While you focus on Google SEO, 73% of shoppers now turn to AI tools for product recommendations. 
          If your products don't appear in ChatGPT, Claude, Gemini, Copilot, or Perplexity—you're invisible, 
          and your competitors are winning.
        </p>
      </div>
    </section>
  );
};

export default Problem;
